const PRECOS_OFICIAIS = {
  essencial: 49.00,
  pro: 97.00,
  empresa: 197.00
};

function sanitizeAscii(str, maxLen) {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9 .\-]/g, '')
    .trim()
    .toUpperCase()
    .slice(0, maxLen);
}

function tlv(id, value) {
  const valStr = String(value);
  const len = String(valStr.length).padStart(2, '0');
  return `${id}${len}${valStr}`;
}

function crc16ccitt(payload) {
  let crc = 0xFFFF;
  for (let i = 0; i < payload.length; i++) {
    crc ^= (payload.charCodeAt(i) << 8);
    for (let j = 0; j < 8; j++) {
      if ((crc & 0x8000) !== 0) {
        crc = ((crc << 1) ^ 0x1021) & 0xFFFF;
      } else {
        crc = (crc << 1) & 0xFFFF;
      }
    }
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

function gerarBrCode({ chave, nome, cidade, valor, txid }) {
  const gui = tlv('00', 'br.gov.bcb.pix');
  const keyField = tlv('01', chave);
  const merchantAccount = tlv('26', gui + keyField);
  const amount = Number(valor).toFixed(2);
  const addData = tlv('62', tlv('05', txid));

  const semCrc =
    tlv('00', '01') +
    merchantAccount +
    tlv('52', '0000') +
    tlv('53', '986') +
    tlv('54', amount) +
    tlv('58', 'BR') +
    tlv('59', nome || '3JR AGENCIA DIGITAL') +
    tlv('60', cidade || 'JI-PARANA') +
    addData +
    '6304';

  return semCrc + crc16ccitt(semCrc);
}

const pixChave = String($env.PIX_CHAVE || '').trim();
const recebedorNome = sanitizeAscii($env.PIX_RECEBEDOR_NOME || '3JR AGENCIA DIGITAL', 25) || '3JR AGENCIA DIGITAL';
const recebedorCidade = sanitizeAscii($env.PIX_RECEBEDOR_CIDADE || 'JI-PARANA', 15) || 'JI-PARANA';
const n8nBaseUrl = String($env.N8N_PUBLIC_URL || 'https://n8n.minhaempresaautonoma.online').replace(/\/+$/, '');
const founderRaw = String($env.FOUNDER_WHATSAPP || '5569993768304').replace(/\D/g, '');
const founderChatId = `${founderRaw}@c.us`;

const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json || {};
  const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

  const planoKey = String(body.plano || 'pro').trim().toLowerCase();
  const valorNum = PRECOS_OFICIAIS[planoKey] || PRECOS_OFICIAIS.pro;
  const valorMensal = Number(valorNum.toFixed(2));

  const empresa = String(body.empresa || 'Cliente AtendeJá').trim();
  const atendente = String(body.atendente || 'Atendente').trim();
  const nicho = String(body.nicho || 'geral').trim();
  const whatsapp = String(body.whatsapp || '').replace(/\D/g, '');
  const cidade = String(body.cidade || '').trim();
  const metodoPagamento = String(body.metodoPagamento || 'PIX').trim().toUpperCase();

  const pedidoId = `ATJ${Date.now().toString().slice(-8)}${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
  const txid = pedidoId.replace(/[^a-zA-Z0-9]/g, '').slice(0, 25);

  const pixCopiaECola = pixChave
    ? gerarBrCode({ chave: pixChave, nome: recebedorNome, cidade: recebedorCidade, valor: valorNum, txid })
    : '';

  const confirmUrl = `${n8nBaseUrl}/webhook/atendeja/confirmar-pix?pedidoId=${encodeURIComponent(pedidoId)}&whatsapp=${encodeURIComponent(whatsapp)}&empresa=${encodeURIComponent(empresa)}&atendente=${encodeURIComponent(atendente)}&nicho=${encodeURIComponent(nicho)}&plano=${encodeURIComponent(planoKey)}`;

  const msgFundador = `💳 *Novo Pedido Pix — AtendeJá*\nPedido: ${pedidoId}\nEmpresa: ${empresa} (${nicho})\nAtendente: ${atendente}\nPlano: ${planoKey.toUpperCase()} — R$ ${valorNum.toFixed(2)}\nWhatsApp: ${whatsapp || 'não informado'}\n\n✅ Após conferir o Pix, confirme em 1 clique:\n${confirmUrl}`;

  results.push({
    json: {
      ok: Boolean(pixChave),
      erro: pixChave ? null : 'Variável $env.PIX_CHAVE não configurada no n8n.',
      pedidoId,
      plano: planoKey,
      valorMensal,
      pixCopiaECola,
      status: 'aguardando_pagamento',
      empresa,
      atendente,
      nicho,
      whatsapp,
      cidade,
      metodoPagamento,
      confirmUrl,
      founderChatId,
      msgFundador
    }
  });
}

return results;

const appBaseUrl = String($env.ATENDEJA_APP_URL || 'https://atendeja.3jr.com.br').replace(/\/+$/, '');
const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json || {};
  const q = raw.query && typeof raw.query === 'object' ? raw.query : raw;

  const pedidoId = String(q.pedidoId || '').trim();
  const empresa = String(q.empresa || 'Sua Empresa').trim();
  const atendente = String(q.atendente || 'Equipe').trim();
  const nicho = String(q.nicho || 'geral').trim();
  const plano = String(q.plano || 'pro').trim();

  let digits = String(q.whatsapp || '').replace(/\D/g, '');
  if (digits && !digits.startsWith('55') && (digits.length === 10 || digits.length === 11)) {
    digits = `55${digits}`;
  }
  const clienteChatId = digits ? `${digits}@c.us` : '';

  const linkAtendeJa = `${appBaseUrl}/?atendente=${encodeURIComponent(atendente)}&empresa=${encodeURIComponent(empresa)}&nicho=${encodeURIComponent(nicho)}`;
  const msgCliente = `Olá, ${atendente}! 🎉 Seu pagamento Pix (${pedidoId}) do *AtendeJá* (Plano ${plano.toUpperCase()}) para *${empresa}* foi confirmado!\n\nSeu acesso já está ativo:\n${linkAtendeJa}\n\nConte com a 3 J R Agência Digital!`;

  const escapeHtml = (s) => String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

  const htmlConfirmacao = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pix Confirmado — AtendeJá</title><style>body{font-family:system-ui,-apple-system,sans-serif;background:#0f172a;color:#f8fafc;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;padding:24px}.card{background:#1e293b;border:1px solid #334155;border-radius:16px;max-width:480px;width:100%;padding:32px;box-shadow:0 20px 40px rgba(0,0,0,.4)}h1{margin:0 0 12px;font-size:22px;color:#4ade80}p{margin:8px 0;color:#cbd5e1;line-height:1.5}.tag{display:inline-block;background:#064e3b;color:#6ee7b7;padding:4px 10px;border-radius:999px;font-size:13px;font-weight:600;margin-bottom:16px}code{background:#0f172a;padding:2px 6px;border-radius:6px;color:#fbbf24}</style></head><body><div class="card"><span class="tag">Pagamento Confirmado</span><h1>Conta AtendeJá Ativada!</h1><p><strong>Pedido:</strong> <code>${escapeHtml(pedidoId || 'N/A')}</code></p><p><strong>Empresa:</strong> ${escapeHtml(empresa)} (${escapeHtml(nicho)})</p><p><strong>Plano:</strong> ${escapeHtml(plano.toUpperCase())}</p><p><strong>WhatsApp notificado:</strong> ${escapeHtml(digits || 'Não informado')}</p><p style="margin-top:16px;font-size:14px;color:#94a3b8">O cliente recebeu a mensagem de boas-vindas com o link de acesso via WAHA.</p></div></body></html>`;

  results.push({
    json: {
      pedidoId,
      empresa,
      atendente,
      nicho,
      plano,
      whatsappDigits: digits,
      clienteChatId,
      linkAtendeJa,
      msgCliente,
      htmlConfirmacao
    }
  });
}

return results;
